DROP TRIGGER IF EXISTS `tutorial`;
delimiter ;;
CREATE TRIGGER `tutorial` BEFORE INSERT ON `charac_stat` FOR EACH ROW begin
 set new.tutorial_flag=-1;
end
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table pvp_result
-- ----------------------------
DROP TRIGGER IF EXISTS `check_play_count`;
delimiter ;;
CREATE TRIGGER `check_play_count` BEFORE UPDATE ON `pvp_result` FOR EACH ROW BEGIN
    IF NEW.play_count < OLD.play_count THEN
        CALL `Cannot decrease play_count value.`;
    END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
